def create_builtin_templates(Template, TemplateSection, TemplateAttribute):
    created = 0
    for spec in BUILTIN_TEMPLATES:
        template, was_created = Template.objects.get_or_create(
            name=spec['name'],
            is_builtin=True,
            defaults={
                'description': spec['description'],
                'doc_type': spec['doc_type'],
                'is_global': True,
                'display_order': spec['display_order'],
            },
        )
        if was_created:
            created += 1
            parents = {}
            for order, (number, title, description) in enumerate(spec['sections']):
                section = TemplateSection.objects.create(
                    template=template,
                    number=number,
                    title=title,
                    description=description,
                    order=order,
                    parent=parents.get(number.rpartition('.')[0]),
                )
                parents[number] = section
        for order, (name, field_type, options) in enumerate(spec['attributes']):
            TemplateAttribute.objects.get_or_create(
                template=template,
                name=name,
                defaults={'field_type': field_type, 'options': options, 'order': order},
            )
    return created


def add_builtin_templates(apps, schema_editor):
    Template = apps.get_model('doctemplates', 'Template')
    TemplateSection = apps.get_model('doctemplates', 'TemplateSection')
    TemplateAttribute = apps.get_model('doctemplates', 'TemplateAttribute')
    created = create_builtin_templates(Template, TemplateSection, TemplateAttribute)
    print(f'Built-in templates: {created} created')


